/**
 * Format a month and year, using the long name for the month.
 *
 * @param {integer} year
 * @param {integer} month - Zero-indexed.
 * @returns {string}
 */
formatMonthLong(year, month) {
  return getFormatter({ month: "long", year: "numeric" }).format(new Date(year, month, 15));
},

/**
 * Format an interval using the month names and year(s).
 *
 * @param {integer} startYear
 * @param {integer} startMonth - Zero-indexed.
 * @param {integer} endYear
 * @param {integer} endMonth - Zero-indexed.
 * @returns {string}
 */
formatMonthInterval(startYear, startMonth, endYear, endMonth) {
  return getFormatter({ month: "long", year: "numeric" }).formatRange(
    new Date(startYear, startMonth, 15),
    new Date(endYear, endMonth, 15)
  );
},

// Set the page title.
const months = container.querySelectorAll("table");
